import os
import unicodedata
from flask import Flask, request, abort, send_file, session
from functools import wraps
import hashlib
import hmac
import re

app = Flask(__name__)
app.secret_key = os.urandom(32)

BASE_DIR = '/var/app/user_files'
FORBIDDEN_PATTERNS = [b'..', b'\x00']

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            abort(401)
        return f(*args, **kwargs)
    return decorated

def is_safe_path(filepath, base_dir):
    """Verify the resolved path is within the allowed base directory."""
    # Resolve to absolute path
    abs_path = os.path.realpath(filepath)
    abs_base = os.path.realpath(base_dir)
    # Ensure the path starts with the base directory
    if not abs_path.startswith(abs_base + os.sep) and abs_path != abs_base:
        return False
    return True

def sanitize_filename(filename):
    """Remove dangerous characters and patterns from filename."""
    # Block null bytes
    if '\x00' in filename:
        return None
    # Block path traversal sequences
    if '..' in filename:
        return None
    # Block absolute paths
    if filename.startswith('/'):
        return None
    # Only allow certain characters
    if not re.match(r'^[\w\-. /]+$', filename):
        return None
    return filename

def normalize_unicode(text):
    """Normalize unicode text to NFC form for consistent storage lookups."""
    # NFC normalization ensures consistent representation
    return unicodedata.normalize('NFC', text)

def resolve_user_file(user_id, filename):
    """Resolve a user's file path with security checks."""
    user_dir = os.path.join(BASE_DIR, f'user_{user_id}')

    # First, sanitize the raw filename
    clean_name = sanitize_filename(filename)
    if clean_name is None:
        return None

    # Construct the full path
    full_path = os.path.join(user_dir, clean_name)

    # Verify path is within user's directory
    if not is_safe_path(full_path, user_dir):
        return None

    # Apply unicode normalization for consistent filesystem access
    # This ensures files are found regardless of unicode representation
    normalized_path = normalize_unicode(full_path)

    return normalized_path

@app.route('/files/<path:filename>')
@require_auth
def serve_file(filename):
    """Serve a file from the user's directory."""
    user_id = session['user_id']

    resolved = resolve_user_file(user_id, filename)
    if resolved is None:
        abort(403)

    if not os.path.isfile(resolved):
        abort(404)

    return send_file(resolved)

@app.route('/files/shared/<path:filename>')
@require_auth
def serve_shared_file(filename):
    """Serve a file from the shared directory."""
    shared_dir = os.path.join(BASE_DIR, 'shared')

    clean_name = sanitize_filename(filename)
    if clean_name is None:
        abort(403)

    full_path = os.path.join(shared_dir, clean_name)

    if not is_safe_path(full_path, shared_dir):
        abort(403)

    # Normalize for consistent access
    normalized_path = normalize_unicode(full_path)

    if not os.path.isfile(normalized_path):
        abort(404)

    return send_file(normalized_path)

@app.route('/upload', methods=['POST'])
@require_auth
def upload_file():
    """Upload a file to the user's directory."""
    user_id = session['user_id']
    user_dir = os.path.join(BASE_DIR, f'user_{user_id}')

    if 'file' not in request.files:
        abort(400)

    f = request.files['file']
    filename = f.filename

    # Sanitize
    clean_name = sanitize_filename(filename)
    if clean_name is None:
        abort(403)

    # Normalize unicode in filename before saving
    clean_name = normalize_unicode(clean_name)

    dest = os.path.join(user_dir, clean_name)

    if not is_safe_path(dest, user_dir):
        abort(403)

    os.makedirs(os.path.dirname(dest), exist_ok=True)
    f.save(dest)
    return {'status': 'ok', 'filename': clean_name}, 201

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
